// ============================================================
// TutorBot · Calcular indicadores para coordinacion academica
// Todos los numeros salen de TUTORIAS: cada indicador es rastreable
// hasta filas concretas de la hoja (requisito de trazabilidad).
// Ventana: ultimos VENTANA_DIAS dias segun fecha_solicitud.
// ============================================================
const cfg = $('Config').first().json;
const VENTANA = Number(cfg.VENTANA_REPORTE_DIAS || 7);

const aDias = f => { const p = String(f).split('-').map(Number); return Date.UTC(p[0], p[1] - 1, p[2]) / 86400000; };
const aFecha = d => new Date(d * 86400000).toISOString().slice(0, 10);

function filas(nodo) {
  try { return $(nodo).all().map(i => i.json).filter(r => r && Object.keys(r).length > 0); }
  catch (e) { return []; }
}
const tutorias = filas('Leer TUTORIAS').filter(t => String(t.id_tutoria || '') !== '');
const tutores  = filas('Leer TUTORES').filter(t => String(t.id_tutor || '') !== '');

// ------------------------------------------------------------
// Periodo: lo pide el formulario, o por defecto los ultimos VENTANA dias.
// El nodo del formulario no existe cuando dispara el reloj, asi que la
// lectura va protegida. Toda fecha recibida se valida: nada entra crudo.
// ------------------------------------------------------------
function fechaValida(v) {
  let f = String(v == null ? '' : v).trim();
  // Se acepta AAAA-MM-DD o un ISO completo. Nada mas: recortar los 10 primeros
  // caracteres dejaria pasar cualquier basura pegada detras de una fecha valida.
  const iso = /^(\d{4}-\d{2}-\d{2})T[0-9:.]+(?:Z|[+-]\d{2}:?\d{2})?$/.exec(f);
  if (iso) f = iso[1];
  if (!/^\d{4}-\d{2}-\d{2}$/.test(f)) return '';
  const p = f.split('-').map(Number);
  const d = new Date(Date.UTC(p[0], p[1] - 1, p[2]));
  const real = d.getUTCFullYear() === p[0] && d.getUTCMonth() === p[1] - 1 && d.getUTCDate() === p[2];
  return real ? f : '';
}

// Tres disparadores posibles. Solo uno se ejecuta por corrida, asi que las
// lecturas de los otros dos lanzan error y se capturan.
function nodo(nombre) {
  try { return $(nombre).first().json || null; } catch (e) { return null; }
}
const formulario = nodo('Solicitud de reporte');
const web = formulario ? null : nodo('Webhook reporte a demanda');

let origen = 'programado';
let pedido = { desde: '', hasta: '' };

if (formulario) {
  origen = 'formulario';
  pedido = { desde: formulario['Desde'], hasta: formulario['Hasta'] };
} else if (web) {
  origen = 'webhook';
  const q = (web.query || web.body || {});
  pedido = { desde: q.desde, hasta: q.hasta };
}

const porDefecto = { desde: aFecha(aDias(cfg.hoy) - VENTANA), hasta: cfg.hoy };
let desde = porDefecto.desde;
let hasta = porDefecto.hasta;
let aviso = '';

const pidioAlgo = String(pedido.desde || '').trim() !== '' || String(pedido.hasta || '').trim() !== '';

if (origen !== 'programado' && pidioAlgo) {
  let d = fechaValida(pedido.desde);
  let h = fechaValida(pedido.hasta);

  if (!d || !h) {
    aviso = 'Alguna fecha recibida no era valida (formato AAAA-MM-DD); se usaron los ultimos ' + VENTANA + ' dias.';
  } else {
    if (d > h) { const tmp = d; d = h; h = tmp; aviso = 'Las fechas venian invertidas; se corrigio el orden.'; }
    if (aDias(h) - aDias(d) > 366) {
      h = aFecha(aDias(d) + 366);
      aviso = 'El rango superaba un ano; se recorto a 366 dias.';
    }
    desde = d;
    hasta = h;
  }
}
const enVentana = tutorias.filter(t => {
  const ref = String(t.fecha_solicitud || '').slice(0, 10) || String(t.fecha || '');
  return ref >= desde && ref <= hasta;
});

const cuenta = est => enVentana.filter(t => String(t.estado || '').toUpperCase() === est).length;
const total = enVentana.length;
const solicitadas   = cuenta('SOLICITADA');
const asignadas     = cuenta('ASIGNADA');
const confirmadas   = cuenta('CONFIRMADA');
const finalizadas   = cuenta('FINALIZADA');
const canceladas    = cuenta('CANCELADA');
const sinCobertura  = cuenta('SIN_DISPONIBILIDAD');

const conTutor = asignadas + confirmadas + finalizadas;
const denom = conTutor + sinCobertura;
const cobertura = denom > 0 ? Math.round((conTutor / denom) * 1000) / 10 : 0;

// Demanda no cubierta por materia (lo que la coordinacion necesita para contratar)
const sinCubrir = {};
enVentana.filter(t => String(t.estado || '').toUpperCase() === 'SIN_DISPONIBILIDAD')
  .forEach(t => {
    const k = (t.materia || 'sin materia') + ' · ' + (t.motivo || 'sin motivo');
    sinCubrir[k] = (sinCubrir[k] || 0) + 1;
  });
const topSinCubrir = Object.entries(sinCubrir).sort((a, b) => b[1] - a[1]).slice(0, 5);

// Carga por tutor (solo estados que consumen agenda)
const carga = {};
enVentana.filter(t => ['ASIGNADA', 'CONFIRMADA', 'FINALIZADA'].includes(String(t.estado || '').toUpperCase()))
  .forEach(t => {
    const k = t.nombre_tutor || t.id_tutor || 'sin tutor';
    carga[k] = (carga[k] || 0) + 1;
  });
const topCarga = Object.entries(carga).sort((a, b) => b[1] - a[1]).slice(0, 8);

const activos = tutores.filter(t => String(t.estado || '').toLowerCase() === 'activo').length;
const sinActividad = tutores
  .filter(t => String(t.estado || '').toLowerCase() === 'activo' && !carga[t.nombre] && !carga[t.id_tutor])
  .map(t => t.nombre).slice(0, 8);

const proximas = tutorias.filter(t =>
  ['ASIGNADA', 'CONFIRMADA'].includes(String(t.estado || '').toUpperCase()) &&
  String(t.fecha) >= cfg.hoy
).length;

let mensaje = [
  'REPORTE TUTORBOT · ' + desde + ' a ' + hasta,
  '',
  'Solicitudes registradas: ' + total,
  '  SOLICITADA (sin cerrar): ' + solicitadas,
  '  ASIGNADA: ' + asignadas,
  '  CONFIRMADA: ' + confirmadas,
  '  FINALIZADA: ' + finalizadas,
  '  CANCELADA: ' + canceladas,
  '  SIN_DISPONIBILIDAD: ' + sinCobertura,
  '',
  'Cobertura de la demanda: ' + cobertura + '%',
  '  (' + conTutor + ' con tutor de ' + denom + ' solicitudes resueltas)',
  'Tutorias vigentes a futuro: ' + proximas,
  'Tutores activos: ' + activos,
  '',
  'Demanda NO cubierta:',
  topSinCubrir.length ? topSinCubrir.map(e => '  ' + e[1] + 'x ' + e[0]).join('\n') : '  ninguna en el periodo',
  '',
  'Carga por tutor:',
  topCarga.length ? topCarga.map(e => '  ' + e[0] + ': ' + e[1]).join('\n') : '  sin actividad',
  '',
  sinActividad.length ? 'Tutores activos sin tutorias: ' + sinActividad.join(', ') : 'Todos los tutores activos tuvieron actividad.',
  '',
  'Fuente: hoja TUTORIAS del libro TutorBot_DB. Cada cifra se puede reconstruir filtrando por estado y fecha_solicitud.'
].join('\n');

// ------------------------------------------------------------
// Prompt para el analisis cualitativo (workflow 03)
// El modelo REDACTA sobre cifras ya calculadas. No calcula nada.
// La lista blanca de cifras se usa despues para verificar que no invento datos.
// ------------------------------------------------------------
const cifras = [total, solicitadas, asignadas, confirmadas, finalizadas, canceladas,
                sinCobertura, cobertura, conTutor, denom, proximas, activos]
  .map(Number).filter(v => !isNaN(v));

const prompt_ia = [
  'Eres analista de la coordinacion academica de una universidad.',
  'Con las cifras de abajo escribe un analisis breve para el equipo de coordinacion.',
  '',
  'REGLAS ESTRICTAS:',
  '- Usa UNICAMENTE las cifras entregadas. No calcules, no estimes, no redondees, no inventes numeros.',
  '- No menciones tutores ni materias que no aparezcan en los datos.',
  '- No propongas acciones que impliquen agendar, cancelar o reasignar tutorias.',
  '- Maximo 6 lineas. Sin encabezados, sin vinetas con simbolos raros, sin markdown.',
  '- Escribe en espanol neutro, tono profesional y directo.',
  '',
  'DATOS DEL PERIODO ' + desde + ' a ' + hasta + ':',
  '- Solicitudes registradas: ' + total,
  '- Sin cerrar (SOLICITADA): ' + solicitadas,
  '- Asignadas: ' + asignadas + ', confirmadas: ' + confirmadas + ', finalizadas: ' + finalizadas,
  '- Canceladas: ' + canceladas + ', sin disponibilidad: ' + sinCobertura,
  '- Cobertura de la demanda: ' + cobertura + '% (' + conTutor + ' de ' + denom + ')',
  '- Tutorias vigentes a futuro: ' + proximas,
  '- Tutores activos: ' + activos,
  '- Demanda no cubierta: ' + (topSinCubrir.length ? topSinCubrir.map(e => e[1] + ' de ' + e[0]).join(', ') : 'ninguna'),
  '- Carga por tutor: ' + (topCarga.length ? topCarga.map(e => e[0] + ' ' + e[1]).join(', ') : 'sin actividad'),
  '- Tutores activos sin actividad: ' + (sinActividad.length ? sinActividad.join(', ') : 'ninguno')
].join('\n');

if (aviso) mensaje = mensaje + '\n\nNota sobre el periodo: ' + aviso;

return [{
  json: {
    mensaje: mensaje,
    origen: origen,
    aviso_periodo: aviso,
    prompt_ia: prompt_ia,
    cifras_validas: cifras,
    nombres_validos: Array.from(new Set(
      topSinCubrir.map(e => e[0]).concat(topCarga.map(e => e[0])).concat(sinActividad)
    )),
    reporte_row: {
      id_reporte: 'REP-' + String(cfg.ahora_iso).replace(/[^0-9]/g, '').slice(0, 12),
      generado_en: cfg.ahora_iso,
      periodo_desde: desde,
      periodo_hasta: hasta,
      origen: origen,
      total_solicitudes: total,
      asignadas: asignadas,
      confirmadas: confirmadas,
      finalizadas: finalizadas,
      canceladas: canceladas,
      sin_disponibilidad: sinCobertura,
      cobertura_pct: cobertura,
      detalle: ('origen ' + origen + (aviso ? ' (' + aviso + ')' : '') + ' | ' +
                topSinCubrir.map(e => e[1] + 'x ' + e[0]).join(' | ')).slice(0, 400)
    }
  }
}];

// ============================================================
// TutorBot · Verificar el analisis redactado por la IA
// El modelo redacta sobre cifras ya calculadas. Este nodo comprueba que
// NO haya introducido numeros que el sistema no calculo. Si lo hizo, el
// texto se descarta entero y se envia solo el reporte determinista.
//
//  IA-10 toda cifra citada por el modelo debe existir en la lista blanca
//  IA-11 el reporte se envia igual aunque la IA falle (degradacion elegante)
// ============================================================
const rep = $('Calcular indicadores').first().json;
const entrada = $input.first().json || {};

let texto = entrada.text;
if (texto == null) texto = entrada.output;
if (texto == null) texto = entrada.response;
if (texto && typeof texto === 'object') texto = JSON.stringify(texto);
texto = String(texto == null ? '' : texto).replace(/```[a-z]*/gi, '').trim();

const permitidas = new Set((rep.cifras_validas || []).map(Number));
// Los porcentajes con un decimal (72.7) y los numeros sueltos del texto
const encontrados = (texto.match(/\d+(?:[.,]\d+)?/g) || [])
  .map(s => Number(String(s).replace(',', '.')))
  .filter(v => !isNaN(v));

// Las cifras de las fechas del periodo son legitimas (2026, 09, 01...)
const delPeriodo = new Set(
  String(rep.reporte_row.periodo_desde + '-' + rep.reporte_row.periodo_hasta)
    .split('-').map(Number).filter(v => !isNaN(v))
);

const inventadas = encontrados.filter(v => !permitidas.has(v) && !delPeriodo.has(v));

let estado = 'aceptado';
if (!texto)                       estado = 'descartado_sin_respuesta';
else if (texto.length > 1200)     estado = 'descartado_demasiado_largo';
else if (inventadas.length)       estado = 'descartado_cifra_inventada';

const mensaje = estado === 'aceptado'
  ? rep.mensaje + '\n\n--- LECTURA DE LA IA ---\n' + texto +
    '\n(Texto redactado por Gemini sobre las cifras de arriba. Cifras verificadas contra la hoja.)'
  : rep.mensaje + '\n\n(El analisis automatico no se incluyo: ' + estado.replace('descartado_', '') + '.)';

return [{
  json: {
    mensaje: mensaje,
    reporte_row: Object.assign({}, rep.reporte_row, {
      detalle: String(rep.reporte_row.detalle || '').slice(0, 340) + ' | IA:' + estado
    }),
    ia_estado: estado,
    ia_cifras_inventadas: inventadas,
    ia_texto: texto.slice(0, 1200)
  }
}];
